script:
// Página web do equipamento – identificação.
// Só leitura: GET na raiz, sem login.

fn detect(device, params) {
    let page = device.get("/");
    #{
        status: page.status,
        server: page.headers["server"],
        title: regex_capture(page.body, "(?is)<title[^>]*>\\s*(.*?)\\s*</title>")
    }
}

fn http_headers(device, params) {
    let page = device.get("/");
    let rows = [];
    for name in page.headers.keys() {
        rows.push(#{ header: name, value: page.headers[name] });
    }
    rows
}
